// ESLint 9 flat config — one config for the whole monorepo.
//
// The rules are deliberately few and mostly about correctness: the value of a
// linter on a platform repository is catching the empty catch block, the
// un-awaited promise and the accidental global, not policing semicolons
// (Prettier owns formatting).
import js from '@eslint/js';
import globals from 'globals';

export default [
  {
    ignores: [
      'node_modules/**',
      '.run/**',
      'coverage/**',
      'gitops/**/charts/**', // generated by Kustomize's Helm inflation
      'apps/storefront/public/**', // browser bundle, not linted as Node code
      'rendered/**',
    ],
  },
  js.configs.recommended,
  {
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: {
        ...globals.node,
        ...globals.es2023,
        fetch: 'readonly',
        AbortSignal: 'readonly',
        structuredClone: 'readonly',
      },
    },
    rules: {
      'no-unused-vars': ['error', { argsIgnorePattern: '^_', varsIgnorePattern: '^_' }],
      'no-var': 'error',
      'prefer-const': ['error', { destructuring: 'all' }],
      eqeqeq: ['error', 'smart'],
      'no-throw-literal': 'error',
      'no-return-await': 'error',
      'require-atomic-updates': 'off',
      // Services log through pino, but scripts and CLI helpers legitimately use
      // console; the rule would only produce noise.
      'no-console': 'off',
      // Empty catch blocks are used deliberately (best-effort cleanup); require a
      // comment instead of a rule, handled in review.
      'no-empty': ['error', { allowEmptyCatch: true }],
    },
  },
  {
    files: ['**/test/**/*.js', '**/*.test.js'],
    languageOptions: {
      globals: { ...globals.node, ...globals.es2023 },
    },
    rules: {
      'no-unused-vars': ['warn', { argsIgnorePattern: '^_' }],
    },
  },
  {
    files: ['scripts/**/*.js', 'scripts/**/*.mjs'],
    rules: {
      'no-console': 'off',
    },
  },
];
